import csv, json, re, pathlib
STOP=set('the a an and or of to in on by for with from at as is are be will which who what when where how first next after before against over into between its his her their this that through about confirmed confirm says said say amid new may april june march 2026 2025 2024'.split())
word=re.compile(r\"[A-Za-z][A-Za-z0-9'\\-]{2,}\")
def toks(s):
    s=str(s or '')
    return {w.lower().strip(\"'\\-\") for w in word.findall(s) if w.lower().strip(\"'\\-\") not in STOP and len(w.strip(\"'\\-\"))>3}
def join_fields(fields):
    return ' '.join(str(x or '') for x in fields)
qs=[]
with open('market.csv', newline='') as f:
    for r in csv.DictReader(f):
        if str(r.get('is_resolved','')).lower()=='false':
            text=join_fields([r.get('title'), r.get('background'), r.get('resolution_criteria')])
            qs.append((r['qid'], r['title'], toks(text), r.get('my_prediction','')))
articles=[]
path=pathlib.Path('articles/2026/03/29/articles.jsonl')
with path.open() as f:
    for line in f:
        a=json.loads(line)
        text=join_fields([a.get('title'), a.get('content')])
        articles.append((a.get('title') or '', a.get('source') or '', toks(text)))
hits=[]
for qid,title,qt,pred in qs:
    if not qt: continue
    best=[]
    for atitle,src,at in articles:
        inter=qt & at
        if len(inter)>=3:
            title_t=toks(atitle)
            score=len(inter)+2*len(qt & title_t)
            if score>=5:
                best.append((score,len(inter),atitle,src,', '.join(sorted(list(inter))[:12])))
    if best:
        best=sorted(best, reverse=True)[:5]
        hits.append((best[0][0], qid, title, pred, best))
for top,qid,title,pred,best in sorted(hits, reverse=True)[:90]:
    print('\\n##', qid, 'score', top)
    print(title)
    print('pred', pred)
    for s,n,atitle,src,terms in best[:3]:
        print(' -', s, src, atitle[:150], '|', terms)
